package dev.arena.liquidglasslab;

/**
 * The AGSL sources shipped with the app.
 *
 * <p>{@link #LIQUID_GLASS} is the exact same shader that
 * {@code shader/liquid_glass.sksl} holds and that {@code tools/skialab.py} renders
 * offline. It is generated by {@code tools/sync_shader.py} — never edit by hand.
 */
public final class Shaders {

    public static final String KEY = "liquid_glass";

    private Shaders() {
    }

    public static final String LIQUID_GLASS = ""
            + "uniform shader content;\n"
            + "uniform float2 uOrigin;\n"
            + "uniform float2 uSize;\n"
            + "uniform float4 uRadii;\n"
            + "uniform float  uBevel;\n"
            + "uniform float  uLens;\n"
            + "uniform float  uLensProfile;\n"
            + "uniform float  uDepth;\n"
            + "uniform float  uChroma;\n"
            + "uniform float4 uTint;\n"
            + "uniform float  uHighlight;\n"
            + "uniform float  uHighlightWidth;\n"
            + "uniform float  uHighlightFalloff;\n"
            + "uniform float2 uLightDir;\n"
            + "uniform float  uInnerShadow;\n"
            + "uniform float  uPress;\n"
            + "uniform float2 uPressPoint;\n"
            + "uniform float  uPressBulge;\n"
            + "uniform float  uGrain;\n"
            + "uniform float  uOpacity;\n"
            + "float sdRoundRect(float2 p, float2 hs, float4 r) {\n"
            + "    float rt = (p.x >= 0.0) ? r.y : r.x;\n"
            + "    float rb = (p.x >= 0.0) ? r.w : r.z;\n"
            + "    float rr = min((p.y >= 0.0) ? rb : rt, min(hs.x, hs.y));\n"
            + "    float2 q = abs(p) - hs + rr;\n"
            + "    return min(max(q.x, q.y), 0.0) + length(max(q, float2(0.0))) - rr;\n"
            + "}\n"
            + "float sdShape(float2 p) {\n"
            + "    return sdRoundRect(p - uOrigin - uSize * 0.5, uSize * 0.5, uRadii);\n"
            + "}\n"
            + "float2 gradShape(float2 p) {\n"
            + "    const float e = 0.75;\n"
            + "    float gx = sdShape(p + float2(e, 0.0)) - sdShape(p - float2(e, 0.0));\n"
            + "    float gy = sdShape(p + float2(0.0, e)) - sdShape(p - float2(0.0, e));\n"
            + "    float2 g = float2(gx, gy);\n"
            + "    float l = length(g);\n"
            + "    return (l > 1e-5) ? g / l : float2(0.0);\n"
            + "}\n"
            + "float circleMap(float x) { return 1.0 - sqrt(max(1.0 - x * x, 0.0)); }\n"
            + "float hash21(float2 p) {\n"
            + "    p = fract(p * float2(123.34, 456.21));\n"
            + "    p += dot(p, p + 45.32);\n"
            + "    return fract(p.x * p.y);\n"
            + "}\n"
            + "half4 main(float2 coord) {\n"
            + "    float sd = sdShape(coord);\n"
            + "    float cov = smoothstep(0.75, -0.75, sd);\n"
            + "    if (cov <= 0.0) return half4(0.0);\n"
            + "    float2 grad = gradShape(coord);\n"
            + "    float distIn = max(-sd, 0.0);\n"
            + "    float bevel = max(uBevel, 0.5);\n"
            + "    float t = clamp(distIn / bevel, 0.0, 1.0);\n"
            + "    float disp = uLens * pow(circleMap(1.0 - t), max(uLensProfile, 0.05));\n"
            + "    float2 c = (coord - uOrigin - uSize * 0.5) / max(uSize * 0.5, float2(1.0));\n"
            + "    disp += uDepth * uLens * 0.22 * (1.0 - t) * (1.0 - min(length(c), 1.0) * 0.5);\n"
            + "    if (uPress > 0.0) {\n"
            + "        float2 pp = coord - uOrigin - uPressPoint;\n"
            + "        float sigma = max(min(uSize.x, uSize.y) * 0.38, 8.0);\n"
            + "        disp += uPressBulge * uPress * exp(-dot(pp, pp) / (2.0 * sigma * sigma));\n"
            + "    }\n"
            + "    float3 col;\n"
            + "    if (uChroma > 0.001) {\n"
            + "        float k = uChroma * 0.12;\n"
            + "        float3 a = content.eval(coord + grad * disp * (1.0 + k)).rgb;\n"
            + "        float3 b = content.eval(coord + grad * disp).rgb;\n"
            + "        float3 d = content.eval(coord + grad * disp * (1.0 - k)).rgb;\n"
            + "        col = float3(a.r, b.g, d.b);\n"
            + "    } else {\n"
            + "        col = content.eval(coord + grad * disp).rgb;\n"
            + "    }\n"
            + "    col = mix(col, uTint.rgb, clamp(uTint.a, 0.0, 1.0));\n"
            + "    float facing = dot(grad, uLightDir);\n"
            + "    float band = exp(-distIn / max(uHighlightWidth, 0.5));\n"
            + "    float spec = pow(max(facing, 0.0), max(uHighlightFalloff, 0.5)) * band * uHighlight;\n"
            + "    float shade = pow(max(-facing, 0.0), max(uHighlightFalloff, 0.5)) * band;\n"
            + "    col += float3(spec) * 1.0;\n"
            + "    col *= 1.0 - 0.35 * shade * 0.5;\n"
            + "    float hair = exp(-distIn / max(uHighlightWidth * 0.55, 0.35));\n"
            + "    col += float3(1.0) * hair * 0.07 * uHighlight;\n"
            + "    float inner = exp(-distIn / max(bevel * 0.85, 0.5));\n"
            + "    float vy = clamp((coord.y - uOrigin.y) / max(uSize.y, 1.0), 0.0, 1.0);\n"
            + "    float downward = mix(0.30, 1.0, smoothstep(0.0, 1.0, vy));\n"
            + "    col *= 1.0 - clamp(uInnerShadow, 0.0, 1.0) * inner * downward;\n"
            + "    if (uGrain > 0.0) {\n"
            + "        col += float3((hash21(coord) - 0.5) * 0.035 * uGrain);\n"
            + "    }\n"
            + "    float a = cov * clamp(uOpacity, 0.0, 1.0);\n"
            + "    return half4(half3(col * a), half(a));\n"
            + "}\n";
}
